// The final challenge! Use all your skills.
// Hint: explore the maze step by step

function tryMove() {
  if (isPathClear()) {
    moveForward();
    if (onGem()) collectGem();
    return true;
  }
  return false;
}

// Write your maze-solving code here!
while (!atGoal()) {
  if (!tryMove()) {
    turnRight();
  }
}
